#!/usr/bin/env python3
"""Prepend a cover page to report.pdf with title 'Annual Financial Report' and the current date.

Task-local helper: builds a one-page letter-size cover, prepends it to the
existing report pages, atomically replaces report.pdf, then validates page 1.
Uses pikepdf if available; otherwise a pure-stdlib incremental PDF update.
Only touches report.pdf (plus a temporary file that atomically replaces it).
"""
import os
import re
import tempfile
import zlib
from datetime import date

INPUT = "report.pdf"
TITLE = "Annual Financial Report"
DATE_STR = date.today().strftime("%B %d, %Y")

try:
    import pikepdf  # noqa: F401
    HAVE_PIKEPDF = True
except ImportError:
    HAVE_PIKEPDF = False


def escape_ps(s):
    return s.replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)")


def build_cover_content():
    """Return (content_bytes, approx) letter-size cover with title and date."""
    w_title = 0.55 * 28 * len(TITLE)
    x1 = (612 - w_title) / 2.0
    w_date = 0.5 * 16 * len(DATE_STR)
    x2 = (612 - w_date) / 2.0
    content = (
        "BT\n/F1 28 Tf\n%.2f %.2f Td\n(%s) Tj\nET\n"
        "BT\n/F2 16 Tf\n%.2f %.2f Td\n(%s) Tj\nET\n"
        % (x1, 520.0, escape_ps(TITLE), x2, 470.0, escape_ps(DATE_STR))
    ).encode("latin-1")
    return content


# --------------------------------------------------------------------------
# pikepdf fast path
# --------------------------------------------------------------------------
def add_cover_pikepdf():
    import pikepdf
    from pikepdf import Name

    content = build_cover_content()
    with pikepdf.open(INPUT) as pdf:
        pdf.pages.insert(0, pdf.add_blank_page(page_size=(612, 792)))
        page = pdf.pages[0]
        page.Resources.Font = pikepdf.Dictionary({
            Name.F1: pdf.make_indirect(pikepdf.Dictionary({
                Name.Type: Name.Font, Name.Subtype: Name.Type1,
                Name.BaseFont: Name.HelveticaBold, Name.Encoding: Name.WinAnsiEncoding,
            })),
            Name.F2: pdf.make_indirect(pikepdf.Dictionary({
                Name.Type: Name.Font, Name.Subtype: Name.Type1,
                Name.BaseFont: Name.Helvetica, Name.Encoding: Name.WinAnsiEncoding,
            })),
        })
        page.Contents = pdf.make_indirect(pikepdf.Stream(pdf, content))
        expected = len(pdf.pages)
        fd, tmp = tempfile.mkstemp(prefix="report_cover_", suffix=".pdf",
                                   dir=os.path.dirname(INPUT) or ".")
        try:
            with os.fdopen(fd, "wb") as f:
                pdf.save(f)
            os.replace(tmp, INPUT)
        except Exception:
            if os.path.exists(tmp):
                os.unlink(tmp)
            raise

    with pikepdf.open(INPUT) as check:
        if len(check.pages) != expected:
            raise SystemExit("validation failed: pikepdf page count mismatch")
        cs = check.pages[0].Contents.read_bytes()
        if TITLE.encode("latin-1") not in cs or DATE_STR.encode("latin-1") not in cs:
            raise SystemExit("validation failed: cover text missing")
    return expected


# --------------------------------------------------------------------------
# Pure-stdlib incremental PDF update
# --------------------------------------------------------------------------
class PdfParseError(Exception):
    pass


def skip_ws(data, pos, end):
    while pos < end and data[pos] in b" \t\r\n\f\0":
        pos += 1
    return pos


def parse_literal_string(data, pos, end):
    pos += 1
    out = bytearray()
    depth = 1
    while pos < end:
        c = data[pos]
        if c == 0x5C:  # backslash
            pos += 1
            if pos >= end:
                break
            e = data[pos]
            if e in b"nrtbf":
                out.append({ord("n"): 10, ord("r"): 13, ord("t"): 9,
                            ord("b"): 8, ord("f"): 12}[e])
                pos += 1
            elif e == ord("\r"):
                pos += 1
                if pos < end and data[pos] == ord("\n"):
                    pos += 1
            elif e == ord("\n"):
                pos += 1
            elif 0x30 <= e <= 0x37:
                m = re.match(rb"[0-7]{1,3}", data[pos:pos + 3])
                out.append(int(m.group(0), 8) & 0xFF)
                pos += m.end()
            else:
                out.append(e)
                pos += 1
        elif c == ord("("):
            depth += 1
            out.append(c)
            pos += 1
        elif c == ord(")"):
            depth -= 1
            pos += 1
            if depth == 0:
                break
            out.append(c)
        else:
            out.append(c)
            pos += 1
    return bytes(out), pos


def parse_hex_string(data, pos, end):
    pos += 1
    out = bytearray()
    hexbuf = []
    while pos < end and data[pos] != ord(">"):
        c = data[pos]
        if c not in b" \t\r\n\f":
            hexbuf.append(chr(c))
        pos += 1
    if pos < end:
        pos += 1
    if len(hexbuf) % 2:
        hexbuf.append("0")
    for i in range(0, len(hexbuf), 2):
        out.append(int("".join(hexbuf[i:i + 2]), 16))
    return bytes(out), pos


def parse_value(data, pos, end):
    while True:
        pos = skip_ws(data, pos, end)
        if pos < end and data[pos] == ord("%"):
            while pos < end and data[pos] not in b"\r\n":
                pos += 1
            continue
        break
    if pos >= end:
        raise PdfParseError("unexpected EOF in value")
    c = data[pos]
    if c == ord("/"):
        pos += 1
        start = pos
        while pos < end and data[pos] not in b"()<>[]{}/% \t\r\n\f":
            pos += 1
        return data[start:pos], pos
    if c == ord("("):
        return parse_literal_string(data, pos, end)
    if c == ord("<"):
        if pos + 1 < end and data[pos + 1] == ord("<"):
            return parse_dict(data, pos, end)
        return parse_hex_string(data, pos, end)
    if c == ord("["):
        pos += 1
        arr = []
        while True:
            pos = skip_ws(data, pos, end)
            if pos >= end:
                raise PdfParseError("array unterminated")
            if data[pos] == ord("]"):
                pos += 1
                break
            v, pos = parse_value(data, pos, end)
            arr.append(v)
        return arr, pos
    if c in b"]>":
        raise PdfParseError("unexpected closing bracket")
    # number / reference / keyword
    start = pos
    while pos < end and data[pos] not in b"()<>[]{}/% \t\r\n\f":
        pos += 1
    tok = data[start:pos]
    m = re.match(rb"([+-]?(?:\d+\.?\d*|\.\d+))", tok)
    if not m:
        if tok == b"true":
            return True, pos
        if tok == b"false":
            return False, pos
        if tok == b"null":
            return None, pos
        raise PdfParseError("unrecognized token %r" % tok)
    numtok = m.group(1)
    q = skip_ws(data, pos, end)
    m2 = re.match(rb"(\d+)\s+R", data[q:end])
    if m2 is not None:
        return ("ref", int(numtok), int(m2.group(1))), q + m2.end()
    if b"." in numtok:
        return float(numtok), pos
    return int(numtok), pos


def parse_dict(data, pos, end):
    pos += 2  # <<
    pairs = []
    while True:
        pos = skip_ws(data, pos, end)
        if pos >= end:
            raise PdfParseError("dict unterminated")
        if data[pos:pos + 2] == b">>":
            pos += 2
            break
        key, pos = parse_value(data, pos, end)
        if not (isinstance(key, bytes) and key.startswith(b"/")):
            raise PdfParseError("dict key expected")
        val, pos = parse_value(data, pos, end)
        pairs.append((key, val))
    return pairs, pos


def dict_get(pairs, name):
    for k, v in pairs:
        if k == name:
            return v
    return None


def dict_get_number(pairs, name):
    v = dict_get(pairs, name)
    if v is None:
        return None
    if isinstance(v, tuple) and v[0] == "ref":
        return ("ref", v[1], v[2])
    if isinstance(v, bool):
        return int(v)
    return int(v)


def read_object(data, offset):
    m = re.match(rb"(\d+)\s+(\d+)\s+obj\b", data[offset:])
    if not m:
        raise PdfParseError("object header missing at %d" % offset)
    objnum, gen = int(m.group(1)), int(m.group(2))
    pos = offset + m.end()
    val, pos = parse_value(data, pos, len(data))
    stream = None
    q = skip_ws(data, pos, len(data))
    if data[q:q + 6] == b"stream":
        p = q + 6
        if data[p:p + 2] == b"\r\n":
            p += 2
        elif data[p:p + 1] in (b"\n", b"\r"):
            p += 1
        length = dict_get_number(val, "/Length")
        if isinstance(length, tuple):
            raise PdfParseError("indirect /Length not supported here")
        stream = data[p:p + length]
    return objnum, gen, val, stream


def decode_stream(val, stream):
    filt = dict_get(val, "/Filter")
    if filt is None:
        return stream
    filters = filt if isinstance(filt, list) else [filt]
    for f in filters:
        if f == b"/FlateDecode":
            stream = zlib.decompress(stream)
        else:
            raise PdfParseError("unsupported stream filter %r" % f)
    return stream


def parse_object_stream(dval, sstream):
    n = dict_get_number(dval, "/N")
    first = dict_get_number(dval, "/First")
    header = sstream[:first]
    objs = {}
    for objnum_s, off_s in re.findall(rb"(\d+)\s+(\d+)", header):
        objnum = int(objnum_s)
        off = int(off_s)
        sub = sstream[off:]
        m = re.match(rb"(\d+)\s+(\d+)\s+obj\b", sub)
        if not m:
            raise PdfParseError("objstm entry malformed")
        p = m.end()
        v, _ = parse_value(sub, p, len(sub))
        objs[objnum] = v
    return objs


def parse_xref(data, xref_offset):
    pos = skip_ws(data, xref_offset, len(data))
    if data[pos:pos + 4] == b"xref":
        return parse_xref_table(data, pos)
    return parse_xref_stream(data, pos)


def parse_xref_table(data, pos):
    entries = {}
    pos += 4
    trailer = None
    while True:
        pos = skip_ws(data, pos, len(data))
        if data[pos:pos + 7] == b"trailer":
            trailer, pos = parse_value(data, pos + 7, len(data))
            break
        m = re.match(rb"(\d+)\s+(\d+)", data[pos:])
        if not m:
            raise PdfParseError("xref subsection header missing")
        start, count = int(m.group(1)), int(m.group(2))
        pos += m.end()
        for i in range(count):
            line = data[pos:pos + 20]
            mm = re.match(rb"(\d{10}) (\d{5}) ([nf])", line)
            if not mm:
                raise PdfParseError("xref entry malformed")
            objnum = start + i
            off, gen, kind = int(mm.group(1)), int(mm.group(2)), mm.group(3)
            entries[objnum] = (1 if kind == b"n" else 0, off, gen)
            pos += 20
    if not isinstance(trailer, list):
        raise PdfParseError("xref trailer missing")
    return entries, trailer


def parse_xref_stream(data, pos):
    m = re.match(rb"(\d+)\s+(\d+)\s+obj\b", data[pos:])
    if not m:
        raise PdfParseError("xref stream header missing")
    pos += m.end()
    val, pos = parse_value(data, pos, len(data))
    q = skip_ws(data, pos, len(data))
    if data[q:q + 6] != b"stream":
        raise PdfParseError("xref stream data missing")
    p = q + 6
    if data[p:p + 2] == b"\r\n":
        p += 2
    elif data[p:p + 1] in (b"\n", b"\r"):
        p += 1
    length = dict_get_number(val, "/Length")
    if isinstance(length, tuple):
        raise PdfParseError("indirect /Length in xref stream")
    raw = decode_stream(val, data[p:p + length])
    W = [int(x) for x in dict_get(val, "/W")]
    index = dict_get(val, "/Index")
    if index is None:
        index = [0, dict_get_number(val, "/Size")]
    entries = {}
    p_in = 0
    for s, c in zip(index[0::2], index[1::2]):
        for i in range(c):
            f1 = raw[p_in:p_in + W[0]]
            p_in += W[0]
            f2 = raw[p_in:p_in + W[1]]
            p_in += W[1]
            f3 = raw[p_in:p_in + W[2]]
            p_in += W[2]
            typ = int.from_bytes(f1, "big") if W[0] else 1
            a = int.from_bytes(f2, "big") if W[1] else 0
            b = int.from_bytes(f3, "big") if W[2] else 0
            entries[s + i] = (typ, a, b)
    return entries, val


def resolve_object(objnum, entries, data, cache=None):
    if cache is None:
        cache = {}
    if objnum in cache:
        return cache[objnum]
    e = entries.get(objnum)
    if e is None:
        raise PdfParseError("object %d not in xref" % objnum)
    typ, a, b = e
    if typ == 1:
        on, og, val, stream = read_object(data, a)
        cache[objnum] = (val, stream)
        return val, stream
    if typ == 2:
        sval, sstream = resolve_object(a, entries, data, cache)
        objs = parse_object_stream(sval, sstream)
        for k, v in objs.items():
            cache.setdefault(k, (v, None))
        return cache[objnum]
    raise PdfParseError("object %d is free" % objnum)


def serialize(val):
    if isinstance(val, tuple) and val[0] == "ref":
        return b"%d %d R" % (val[1], val[2])
    if isinstance(val, bytes):
        if val.startswith(b"/"):
            return val
        return b"(" + escape_ps(val.decode("latin-1")).encode("latin-1") + b")"
    if val is True:
        return b"true"
    if val is False:
        return b"false"
    if val is None:
        return b"null"
    if isinstance(val, (int, float)):
        return repr(val).encode("ascii")
    if isinstance(val, list):
        return b"[" + b" ".join(serialize(v) for v in val) + b"]"
    raise PdfParseError("cannot serialize %r" % (val,))


def serialize_pairs(pairs):
    return b" ".join(k + b" " + serialize(v) for k, v in pairs)


def add_cover_pure():
    with open(INPUT, "rb") as f:
        data = f.read()

    idx = data.rfind(b"startxref")
    if idx < 0:
        raise PdfParseError("no startxref found")
    m = re.search(rb"startxref\s+(\d+)", data[idx:])
    old_xref = int(m.group(1))

    entries, trailer = parse_xref(data, old_xref)
    if dict_get(trailer, "/Encrypt") is not None:
        raise SystemExit("error: report.pdf is encrypted; stdlib fallback cannot update it")

    root_ref = dict_get(trailer, "/Root")
    if not (isinstance(root_ref, tuple) and root_ref[0] == "ref"):
        raise PdfParseError("no /Root")
    root_val, _ = resolve_object(root_ref[1], entries, data)
    pages_ref = dict_get(root_val, "/Pages")
    if not (isinstance(pages_ref, tuple) and pages_ref[0] == "ref"):
        raise PdfParseError("no /Pages")
    pages_val, _ = resolve_object(pages_ref[1], entries, data)

    old_count = dict_get_number(pages_val, "/Count")
    old_kids = dict_get(pages_val, "/Kids")
    if not isinstance(old_kids, list):
        raise PdfParseError("no /Kids array")

    size = dict_get_number(trailer, "/Size")
    max_obj = size - 1
    n_cover, n_f1, n_f2, n_cont = max_obj + 1, max_obj + 2, max_obj + 3, max_obj + 4
    pages_objnum, pages_gen = pages_ref[1], pages_ref[2]

    content = build_cover_content()
    cont_body = (b"<< /Length %d >>\nstream\n" % len(content)) + content + b"endstream"
    f1_body = b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>"
    f2_body = b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>"
    cover_body = (b"<< /Type /Page /Parent %d %d R /MediaBox [0 0 612 792] "
                  b"/Resources << /Font << /F1 %d 0 R /F2 %d 0 R >> >> "
                  b"/Contents %d 0 R >>" % (pages_objnum, pages_gen, n_f1, n_f2, n_cont))

    kids_parts = [b"%d 0 R" % n_cover]
    for r in old_kids:
        if isinstance(r, tuple) and r[0] == "ref":
            kids_parts.append(b"%d %d R" % (r[1], r[2]))
    kept = [(k, v) for k, v in pages_val if k not in (b"/Kids", b"/Count")]
    pages_body = (b"<< /Type /Pages " + serialize_pairs(kept) +
                  b" /Kids [" + b" ".join(kids_parts) + b"] /Count %d >>"
                  % (old_count + 1))

    bodies = {
        pages_objnum: (pages_body, pages_gen),
        n_cover: (cover_body, 0),
        n_f1: (f1_body, 0),
        n_f2: (f2_body, 0),
        n_cont: (cont_body, 0),
    }

    out = bytearray(data)
    offsets = {}
    for objnum in sorted(bodies):
        body, gen = bodies[objnum]
        offsets[objnum] = len(out)
        out += ("%d %d obj\n" % (objnum, gen)).encode("ascii")
        out += body
        out += b"\nendobj\n"
    new_xref = len(out)

    out += b"xref\n0 1\n0000000000 65535 f \n"
    subsections = []
    for objnum in sorted(bodies):
        if not subsections or objnum != subsections[-1][-1] + 1:
            subsections.append([objnum])
        else:
            subsections[-1].append(objnum)
    for sub in subsections:
        out += ("%d %d\n" % (sub[0], len(sub))).encode("ascii")
        for objnum in sub:
            out += ("%010d %05d n \n" % (offsets[objnum], bodies[objnum][1])).encode("ascii")

    new_size = max(bodies) + 1
    out += ("trailer\n<< /Size %d /Root %d %d R /Prev %d >>\nstartxref\n%d\n%%EOF\n"
            % (new_size, root_ref[1], root_ref[2], old_xref, new_xref)).encode("ascii")

    fd, tmp = tempfile.mkstemp(prefix="report_cover_", suffix=".pdf",
                               dir=os.path.dirname(INPUT) or ".")
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(bytes(out))
        os.replace(tmp, INPUT)
    except Exception:
        if os.path.exists(tmp):
            os.unlink(tmp)
        raise

    # ---- validate by re-parsing ----
    with open(INPUT, "rb") as f:
        ndata = f.read()
    nidx = ndata.rfind(b"startxref")
    nm = re.search(rb"startxref\s+(\d+)", ndata[nidx:])
    nentries, ntrailer = parse_xref(ndata, int(nm.group(1)))
    nroot = dict_get(ntrailer, "/Root")
    nroot_val, _ = resolve_object(nroot[1], nentries, ndata)
    npages_ref = dict_get(nroot_val, "/Pages")
    npages_val, _ = resolve_object(npages_ref[1], nentries, ndata)
    ncount = dict_get_number(npages_val, "/Count")
    if ncount != old_count + 1:
        raise SystemExit("validation failed: /Count=%d expected %d"
                         % (ncount, old_count + 1))
    cover_val, _ = resolve_object(n_cover, nentries, ndata)
    cont_ref = dict_get(cover_val, "/Contents")
    cont_val, cont_stream = resolve_object(cont_ref[1], nentries, ndata)
    if TITLE.encode("latin-1") not in cont_stream:
        raise SystemExit("validation failed: cover title missing")
    if DATE_STR.encode("latin-1") not in cont_stream:
        raise SystemExit("validation failed: cover date missing")
    return ncount


# --------------------------------------------------------------------------
def main():
    if not os.path.exists(INPUT):
        raise SystemExit("error: %s not found" % INPUT)

    if HAVE_PIKEPDF:
        try:
            total = add_cover_pikepdf()
            method = "pikepdf"
        except SystemExit:
            raise
        except Exception as exc:
            print("pikepdf path failed (%s); trying stdlib fallback" % exc)
            total = add_cover_pure()
            method = "pure-stdlib"
    else:
        total = add_cover_pure()
        method = "pure-stdlib"

    print("OK: cover page added to %s" % INPUT)
    print("    method: %s" % method)
    print("    title: %s" % TITLE)
    print("    date:  %s" % DATE_STR)
    print("    total pages: %d" % total)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Prepend a cover page to report.pdf with title 'Annual Financial Report' and the current date.

Task-local helper: builds a one-page letter-size cover, prepends it to the
existing report pages, atomically replaces report.pdf, then validates page 1.
Uses pikepdf if available; otherwise a pure-stdlib incremental PDF update.
Only touches report.pdf (plus a temporary file that atomically replaces it).
"""
import os
import re
import tempfile
import zlib
from datetime import date

INPUT = "report.pdf"
TITLE = "Annual Financial Report"
DATE_STR = date.today().strftime("%B %d, %Y")

try:
    import pikepdf  # noqa: F401
    HAVE_PIKEPDF = True
except ImportError:
    HAVE_PIKEPDF = False


def escape_ps(s):
    return s.replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)")


def build_cover_content():
    """Return content-stream bytes for a letter-size cover with title and date."""
    w_title = 0.55 * 28 * len(TITLE)
    x1 = (612 - w_title) / 2.0
    w_date = 0.5 * 16 * len(DATE_STR)
    x2 = (612 - w_date) / 2.0
    content = (
        "BT\n/F1 28 Tf\n%.2f %.2f Td\n(%s) Tj\nET\n"
        "BT\n/F2 16 Tf\n%.2f %.2f Td\n(%s) Tj\nET\n"
        % (x1, 520.0, escape_ps(TITLE), x2, 470.0, escape_ps(DATE_STR))
    ).encode("latin-1")
    return content


# --------------------------------------------------------------------------
# pikepdf fast path
# --------------------------------------------------------------------------
def add_cover_pikepdf():
    import pikepdf
    from pikepdf import Name

    content = build_cover_content()
    with pikepdf.open(INPUT) as pdf:
        pdf.pages.insert(0, pdf.add_blank_page(page_size=(612, 792)))
        page = pdf.pages[0]
        page.Resources.Font = pikepdf.Dictionary({
            Name.F1: pdf.make_indirect(pikepdf.Dictionary({
                Name.Type: Name.Font, Name.Subtype: Name.Type1,
                Name.BaseFont: Name.HelveticaBold, Name.Encoding: Name.WinAnsiEncoding,
            })),
            Name.F2: pdf.make_indirect(pikepdf.Dictionary({
                Name.Type: Name.Font, Name.Subtype: Name.Type1,
                Name.BaseFont: Name.Helvetica, Name.Encoding: Name.WinAnsiEncoding,
            })),
        })
        page.Contents = pdf.make_indirect(pikepdf.Stream(pdf, content))
        expected = len(pdf.pages)
        fd, tmp = tempfile.mkstemp(prefix="report_cover_", suffix=".pdf",
                                   dir=os.path.dirname(INPUT) or ".")
        try:
            with os.fdopen(fd, "wb") as f:
                pdf.save(f)
            os.replace(tmp, INPUT)
        except Exception:
            if os.path.exists(tmp):
                os.unlink(tmp)
            raise

    with pikepdf.open(INPUT) as check:
        if len(check.pages) != expected:
            raise SystemExit("validation failed: pikepdf page count mismatch")
        cs = check.pages[0].Contents.read_bytes()
        if TITLE.encode("latin-1") not in cs or DATE_STR.encode("latin-1") not in cs:
            raise SystemExit("validation failed: cover text missing")
    return expected


# --------------------------------------------------------------------------
# Pure-stdlib incremental PDF update
# --------------------------------------------------------------------------
class PdfParseError(Exception):
    pass


def skip_ws(data, pos, end):
    while pos < end and data[pos] in b" \t\r\n\f\0":
        pos += 1
    return pos


def parse_literal_string(data, pos, end):
    pos += 1
    out = bytearray()
    depth = 1
    while pos < end:
        c = data[pos]
        if c == 0x5C:  # backslash
            pos += 1
            if pos >= end:
                break
            e = data[pos]
            if e in b"nrtbf":
                out.append({ord("n"): 10, ord("r"): 13, ord("t"): 9,
                            ord("b"): 8, ord("f"): 12}[e])
                pos += 1
            elif e == ord("\r"):
                pos += 1
                if pos < end and data[pos] == ord("\n"):
                    pos += 1
            elif e == ord("\n"):
                pos += 1
            elif 0x30 <= e <= 0x37:
                m = re.match(rb"[0-7]{1,3}", data[pos:pos + 3])
                out.append(int(m.group(0), 8) & 0xFF)
                pos += m.end()
            else:
                out.append(e)
                pos += 1
        elif c == ord("("):
            depth += 1
            out.append(c)
            pos += 1
        elif c == ord(")"):
            depth -= 1
            pos += 1
            if depth == 0:
                break
            out.append(c)
        else:
            out.append(c)
            pos += 1
    return bytes(out), pos


def parse_hex_string(data, pos, end):
    pos += 1
    out = bytearray()
    hexbuf = []
    while pos < end and data[pos] != ord(">"):
        c = data[pos]
        if c not in b" \t\r\n\f":
            hexbuf.append(chr(c))
        pos += 1
    if pos < end:
        pos += 1
    if len(hexbuf) % 2:
        hexbuf.append("0")
    for i in range(0, len(hexbuf), 2):
        out.append(int("".join(hexbuf[i:i + 2]), 16))
    return bytes(out), pos


def parse_value(data, pos, end):
    while True:
        pos = skip_ws(data, pos, end)
        if pos < end and data[pos] == ord("%"):
            while pos < end and data[pos] not in b"\r\n":
                pos += 1
            continue
        break
    if pos >= end:
        raise PdfParseError("unexpected EOF in value")
    c = data[pos]
    if c == ord("/"):
        pos += 1
        start = pos
        while pos < end and data[pos] not in b"()<>[]{}/% \t\r\n\f":
            pos += 1
        return data[start:pos], pos
    if c == ord("("):
        return parse_literal_string(data, pos, end)
    if c == ord("<"):
        if pos + 1 < end and data[pos + 1] == ord("<"):
            return parse_dict(data, pos, end)
        return parse_hex_string(data, pos, end)
    if c == ord("["):
        pos += 1
        arr = []
        while True:
            pos = skip_ws(data, pos, end)
            if pos >= end:
                raise PdfParseError("array unterminated")
            if data[pos] == ord("]"):
                pos += 1
                break
            v, pos = parse_value(data, pos, end)
            arr.append(v)
        return arr, pos
    if c in b"]>":
        raise PdfParseError("unexpected closing bracket")
    # number / reference / keyword
    start = pos
    while pos < end and data[pos] not in b"()<>[]{}/% \t\r\n\f":
        pos += 1
    tok = data[start:pos]
    m = re.match(rb"([+-]?(?:\d+\.?\d*|\.\d+))", tok)
    if not m:
        if tok == b"true":
            return True, pos
        if tok == b"false":
            return False, pos
        if tok == b"null":
            return None, pos
        raise PdfParseError("unrecognized token %r" % tok)
    numtok = m.group(1)
    q = skip_ws(data, pos, end)
    m2 = re.match(rb"(\d+)\s+R", data[q:end])
    if m2 is not None:
        return ("ref", int(numtok), int(m2.group(1))), q + m2.end()
    if b"." in numtok:
        return float(numtok), pos
    return int(numtok), pos


def parse_dict(data, pos, end):
    pos += 2  # <<
    pairs = []
    while True:
        pos = skip_ws(data, pos, end)
        if pos >= end:
            raise PdfParseError("dict unterminated")
        if data[pos:pos + 2] == b">>":
            pos += 2
            break
        key, pos = parse_value(data, pos, end)
        if not (isinstance(key, bytes) and key.startswith(b"/")):
            raise PdfParseError("dict key expected")
        val, pos = parse_value(data, pos, end)
        pairs.append((key, val))
    return pairs, pos


def dict_get(pairs, name):
    for k, v in pairs:
        if k == name:
            return v
    return None


def dict_get_number(pairs, name):
    v = dict_get(pairs, name)
    if v is None:
        return None
    if isinstance(v, tuple) and v[0] == "ref":
        return ("ref", v[1], v[2])
    if isinstance(v, bool):
        return int(v)
    return int(v)


def read_object(data, offset):
    m = re.match(rb"(\d+)\s+(\d+)\s+obj\b", data[offset:])
    if not m:
        raise PdfParseError("object header missing at %d" % offset)
    objnum, gen = int(m.group(1)), int(m.group(2))
    pos = offset + m.end()
    val, pos = parse_value(data, pos, len(data))
    stream = None
    q = skip_ws(data, pos, len(data))
    if data[q:q + 6] == b"stream":
        p = q + 6
        if data[p:p + 2] == b"\r\n":
            p += 2
        elif data[p:p + 1] in (b"\n", b"\r"):
            p += 1
        length = dict_get_number(val, "/Length")
        if isinstance(length, tuple):
            raise PdfParseError("indirect /Length not supported here")
        stream = data[p:p + length]
    return objnum, gen, val, stream


def decode_stream(val, stream):
    filt = dict_get(val, "/Filter")
    if filt is None:
        return stream
    filters = filt if isinstance(filt, list) else [filt]
    for f in filters:
        if f == b"/FlateDecode":
            stream = zlib.decompress(stream)
        else:
            raise PdfParseError("unsupported stream filter %r" % f)
    return stream


def parse_object_stream(dval, sstream):
    n = dict_get_number(dval, "/N")
    first = dict_get_number(dval, "/First")
    header = sstream[:first]
    objs = {}
    for objnum_s, off_s in re.findall(rb"(\d+)\s+(\d+)", header):
        objnum = int(objnum_s)
        off = int(off_s)
        sub = sstream[off:]
        m = re.match(rb"(\d+)\s+(\d+)\s+obj\b", sub)
        if not m:
            raise PdfParseError("objstm entry malformed")
        p = m.end()
        v, _ = parse_value(sub, p, len(sub))
        objs[objnum] = v
    return objs


def parse_xref(data, xref_offset):
    pos = skip_ws(data, xref_offset, len(data))
    if data[pos:pos + 4] == b"xref":
        try:
            return parse_xref_table(data, pos)
        except PdfParseError:
            # some generators put an xref stream where 'xref' appears in text
            return parse_xref_stream(data, pos)
    return parse_xref_stream(data, pos)


def parse_xref_table(data, pos):
    entries = {}
    pos += 4  # skip 'xref'
    trailer = None
    while True:
        pos = skip_ws(data, pos, len(data))
        if data[pos:pos + 7] == b"trailer":
            trailer, _ = parse_value(data, pos + 7, len(data))
            break
        m = re.match(rb"(\d+)\s+(\d+)", data[pos:])
        if not m:
            raise PdfParseError("xref subsection header missing at %d" % pos)
        start, count = int(m.group(1)), int(m.group(2))
        pos += m.end()
        pos = skip_ws(data, pos, len(data))
        for i in range(count):
            nl = data.find(b"\n", pos)
            if nl == -1:
                nl = len(data)
            line = data[pos:nl].strip()
            pos = nl + 1
            mm = re.match(rb"(\d+)\s+(\d+)\s+([nf])", line)
            if not mm:
                raise PdfParseError("xref entry malformed: %r" % line[:40])
            objnum = start + i
            off, gen, kind = int(mm.group(1)), int(mm.group(2)), mm.group(3)
            entries[objnum] = (1 if kind == b"n" else 0, off, gen)
    if not isinstance(trailer, list):
        raise PdfParseError("xref trailer missing")
    return entries, trailer


def parse_xref_stream(data, pos):
    m = re.match(rb"(\d+)\s+(\d+)\s+obj\b", data[pos:])
    if not m:
        raise PdfParseError("xref stream header missing at %d" % pos)
    pos += m.end()
    val, pos = parse_value(data, pos, len(data))
    q = skip_ws(data, pos, len(data))
    if data[q:q + 6] != b"stream":
        raise PdfParseError("xref stream data missing")
    p = q + 6
    if data[p:p + 2] == b"\r\n":
        p += 2
    elif data[p:p + 1] in (b"\n", b"\r"):
        p += 1
    length = dict_get_number(val, "/Length")
    if isinstance(length, tuple):
        raise PdfParseError("indirect /Length in xref stream")
    raw = decode_stream(val, data[p:p + length])
    W = [int(x) for x in dict_get(val, "/W")]
    index = dict_get(val, "/Index")
    if index is None:
        index = [0, dict_get_number(val, "/Size")]
    entries = {}
    p_in = 0
    for s, c in zip(index[0::2], index[1::2]):
        for i in range(c):
            f1 = raw[p_in:p_in + W[0]]
            p_in += W[0]
            f2 = raw[p_in:p_in + W[1]]
            p_in += W[1]
            f3 = raw[p_in:p_in + W[2]]
            p_in += W[2]
            typ = int.from_bytes(f1, "big") if W[0] else 1
            a = int.from_bytes(f2, "big") if W[1] else 0
            b = int.from_bytes(f3, "big") if W[2] else 0
            entries[s + i] = (typ, a, b)
    return entries, val


def resolve_object(objnum, entries, data, cache=None):
    if cache is None:
        cache = {}
    if objnum in cache:
        return cache[objnum]
    e = entries.get(objnum)
    if e is None:
        raise PdfParseError("object %d not in xref" % objnum)
    typ, a, b = e
    if typ == 1:
        on, og, val, stream = read_object(data, a)
        cache[objnum] = (val, stream)
        return val, stream
    if typ == 2:
        sval, sstream = resolve_object(a, entries, data, cache)
        objs = parse_object_stream(sval, sstream)
        for k, v in objs.items():
            cache.setdefault(k, (v, None))
        return cache[objnum]
    raise PdfParseError("object %d is free" % objnum)


def serialize(val):
    if isinstance(val, tuple) and val[0] == "ref":
        return b"%d %d R" % (val[1], val[2])
    if isinstance(val, bytes):
        if val.startswith(b"/"):
            return val
        return b"(" + escape_ps(val.decode("latin-1")).encode("latin-1") + b")"
    if val is True:
        return b"true"
    if val is False:
        return b"false"
    if val is None:
        return b"null"
    if isinstance(val, (int, float)):
        return repr(val).encode("ascii")
    if isinstance(val, list):
        return b"[" + b" ".join(serialize(v) for v in val) + b"]"
    raise PdfParseError("cannot serialize %r" % (val,))


def serialize_pairs(pairs):
    return b" ".join(k + b" " + serialize(v) for k, v in pairs)


def add_cover_pure():
    with open(INPUT, "rb") as f:
        data = f.read()

    idx = data.rfind(b"startxref")
    if idx < 0:
        raise PdfParseError("no startxref found")
    m = re.search(rb"startxref\s+(\d+)", data[idx:])
    old_xref = int(m.group(1))

    entries, trailer = parse_xref(data, old_xref)
    if dict_get(trailer, "/Encrypt") is not None:
        raise SystemExit("error: report.pdf is encrypted; stdlib fallback cannot update it")

    root_ref = dict_get(trailer, "/Root")
    if not (isinstance(root_ref, tuple) and root_ref[0] == "ref"):
        raise PdfParseError("no /Root")
    root_val, _ = resolve_object(root_ref[1], entries, data)
    pages_ref = dict_get(root_val, "/Pages")
    if not (isinstance(pages_ref, tuple) and pages_ref[0] == "ref"):
        raise PdfParseError("no /Pages")
    pages_val, _ = resolve_object(pages_ref[1], entries, data)

    old_count = dict_get_number(pages_val, "/Count")
    old_kids = dict_get(pages_val, "/Kids")
    if not isinstance(old_kids, list):
        raise PdfParseError("no /Kids array")

    size = dict_get_number(trailer, "/Size")
    max_obj = size - 1
    n_cover, n_f1, n_f2, n_cont = max_obj + 1, max_obj + 2, max_obj + 3, max_obj + 4
    pages_objnum, pages_gen = pages_ref[1], pages_ref[2]

    content = build_cover_content()
    cont_body = (b"<< /Length %d >>\nstream\n" % len(content)) + content + b"endstream"
    f1_body = b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>"
    f2_body = b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>"
    cover_body = (b"<< /Type /Page /Parent %d %d R /MediaBox [0 0 612 792] "
                  b"/Resources << /Font << /F1 %d 0 R /F2 %d 0 R >> >> "
                  b"/Contents %d 0 R >>" % (pages_objnum, pages_gen, n_f1, n_f2, n_cont))

    kids_parts = [b"%d 0 R" % n_cover]
    for r in old_kids:
        if isinstance(r, tuple) and r[0] == "ref":
            kids_parts.append(b"%d %d R" % (r[1], r[2]))
    kept = [(k, v) for k, v in pages_val if k not in (b"/Kids", b"/Count")]
    pages_body = (b"<< /Type /Pages " + serialize_pairs(kept) +
                  b" /Kids [" + b" ".join(kids_parts) + b"] /Count %d >>"
                  % (old_count + 1))

    bodies = {
        pages_objnum: (pages_body, pages_gen),
        n_cover: (cover_body, 0),
        n_f1: (f1_body, 0),
        n_f2: (f2_body, 0),
        n_cont: (cont_body, 0),
    }

    out = bytearray(data)
    offsets = {}
    for objnum in sorted(bodies):
        body, gen = bodies[objnum]
        offsets[objnum] = len(out)
        out += ("%d %d obj\n" % (objnum, gen)).encode("ascii")
        out += body
        out += b"\nendobj\n"
    new_xref = len(out)

    out += b"xref\n0 1\n0000000000 65535 f \n"
    subsections = []
    for objnum in sorted(bodies):
        if not subsections or objnum != subsections[-1][-1] + 1:
            subsections.append([objnum])
        else:
            subsections[-1].append(objnum)
    for sub in subsections:
        out += ("%d %d\n" % (sub[0], len(sub))).encode("ascii")
        for objnum in sub:
            out += ("%010d %05d n \n" % (offsets[objnum], bodies[objnum][1])).encode("ascii")

    new_size = max(bodies) + 1
    out += ("trailer\n<< /Size %d /Root %d %d R /Prev %d >>\nstartxref\n%d\n%%EOF\n"
            % (new_size, root_ref[1], root_ref[2], old_xref, new_xref)).encode("ascii")

    fd, tmp = tempfile.mkstemp(prefix="report_cover_", suffix=".pdf",
                               dir=os.path.dirname(INPUT) or ".")
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(bytes(out))
        os.replace(tmp, INPUT)
    except Exception:
        if os.path.exists(tmp):
            os.unlink(tmp)
        raise

    # ---- validate by re-parsing ----
    with open(INPUT, "rb") as f:
        ndata = f.read()
    nidx = ndata.rfind(b"startxref")
    nm = re.search(rb"startxref\s+(\d+)", ndata[nidx:])
    nentries, ntrailer = parse_xref(ndata, int(nm.group(1)))
    nroot = dict_get(ntrailer, "/Root")
    nroot_val, _ = resolve_object(nroot[1], nentries, ndata)
    npages_ref = dict_get(nroot_val, "/Pages")
    npages_val, _ = resolve_object(npages_ref[1], nentries, ndata)
    ncount = dict_get_number(npages_val, "/Count")
    if ncount != old_count + 1:
        raise SystemExit("validation failed: /Count=%d expected %d"
                         % (ncount, old_count + 1))
    cover_val, _ = resolve_object(n_cover, nentries, ndata)
    cont_ref = dict_get(cover_val, "/Contents")
    cont_val, cont_stream = resolve_object(cont_ref[1], nentries, ndata)
    if TITLE.encode("latin-1") not in cont_stream:
        raise SystemExit("validation failed: cover title missing")
    if DATE_STR.encode("latin-1") not in cont_stream:
        raise SystemExit("validation failed: cover date missing")
    return ncount


# --------------------------------------------------------------------------
def main():
    if not os.path.exists(INPUT):
        raise SystemExit("error: %s not found" % INPUT)

    if HAVE_PIKEPDF:
        try:
            total = add_cover_pikepdf()
            method = "pikepdf"
        except SystemExit:
            raise
        except Exception as exc:
            print("pikepdf path failed (%s); trying stdlib fallback" % exc)
            total = add_cover_pure()
            method = "pure-stdlib"
    else:
        total = add_cover_pure()
        method = "pure-stdlib"

    print("OK: cover page added to %s" % INPUT)
    print("    method: %s" % method)
    print("    title: %s" % TITLE)
    print("    date:  %s" % DATE_STR)
    print("    total pages: %d" % total)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Prepend a cover page to report.pdf with title 'Annual Financial Report' and the current date.

Task-local helper: builds a one-page letter-size cover, prepends it to the
existing report pages, atomically replaces report.pdf, then validates page 1.
Uses pikepdf if available; otherwise a pure-stdlib incremental PDF update.
Only touches report.pdf (plus a temporary file that atomically replaces it).
"""
import os
import re
import tempfile
import zlib
from datetime import date

INPUT = "report.pdf"
TITLE = "Annual Financial Report"
DATE_STR = date.today().strftime("%B %d, %Y")

try:
    import pikepdf  # noqa: F401
    HAVE_PIKEPDF = True
except ImportError:
    HAVE_PIKEPDF = False


def escape_ps(s):
    return s.replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)")


def build_cover_content():
    """Return content-stream bytes for a letter-size cover with title and date."""
    w_title = 0.55 * 28 * len(TITLE)
    x1 = (612 - w_title) / 2.0
    w_date = 0.5 * 16 * len(DATE_STR)
    x2 = (612 - w_date) / 2.0
    content = (
        "BT\n/F1 28 Tf\n%.2f %.2f Td\n(%s) Tj\nET\n"
        "BT\n/F2 16 Tf\n%.2f %.2f Td\n(%s) Tj\nET\n"
        % (x1, 520.0, escape_ps(TITLE), x2, 470.0, escape_ps(DATE_STR))
    ).encode("latin-1")
    return content


# --------------------------------------------------------------------------
# pikepdf fast path
# --------------------------------------------------------------------------
def add_cover_pikepdf():
    import pikepdf
    from pikepdf import Name

    content = build_cover_content()
    with pikepdf.open(INPUT) as pdf:
        pdf.pages.insert(0, pdf.add_blank_page(page_size=(612, 792)))
        page = pdf.pages[0]
        page.Resources.Font = pikepdf.Dictionary({
            Name.F1: pdf.make_indirect(pikepdf.Dictionary({
                Name.Type: Name.Font, Name.Subtype: Name.Type1,
                Name.BaseFont: Name.HelveticaBold, Name.Encoding: Name.WinAnsiEncoding,
            })),
            Name.F2: pdf.make_indirect(pikepdf.Dictionary({
                Name.Type: Name.Font, Name.Subtype: Name.Type1,
                Name.BaseFont: Name.Helvetica, Name.Encoding: Name.WinAnsiEncoding,
            })),
        })
        page.Contents = pdf.make_indirect(pikepdf.Stream(pdf, content))
        expected = len(pdf.pages)
        fd, tmp = tempfile.mkstemp(prefix="report_cover_", suffix=".pdf",
                                   dir=os.path.dirname(INPUT) or ".")
        try:
            with os.fdopen(fd, "wb") as f:
                pdf.save(f)
            os.replace(tmp, INPUT)
        except Exception:
            if os.path.exists(tmp):
                os.unlink(tmp)
            raise

    with pikepdf.open(INPUT) as check:
        if len(check.pages) != expected:
            raise SystemExit("validation failed: pikepdf page count mismatch")
        cs = check.pages[0].Contents.read_bytes()
        if TITLE.encode("latin-1") not in cs or DATE_STR.encode("latin-1") not in cs:
            raise SystemExit("validation failed: cover text missing")
    return expected


# --------------------------------------------------------------------------
# Pure-stdlib incremental PDF update
# --------------------------------------------------------------------------
class PdfParseError(Exception):
    pass


def skip_ws(data, pos, end):
    while pos < end and data[pos] in b" \t\r\n\f\0":
        pos += 1
    return pos


def parse_literal_string(data, pos, end):
    pos += 1
    out = bytearray()
    depth = 1
    while pos < end:
        c = data[pos]
        if c == 0x5C:  # backslash
            pos += 1
            if pos >= end:
                break
            e = data[pos]
            if e in b"nrtbf":
                out.append({ord("n"): 10, ord("r"): 13, ord("t"): 9,
                            ord("b"): 8, ord("f"): 12}[e])
                pos += 1
            elif e == ord("\r"):
                pos += 1
                if pos < end and data[pos] == ord("\n"):
                    pos += 1
            elif e == ord("\n"):
                pos += 1
            elif 0x30 <= e <= 0x37:
                m = re.match(rb"[0-7]{1,3}", data[pos:pos + 3])
                out.append(int(m.group(0), 8) & 0xFF)
                pos += m.end()
            else:
                out.append(e)
                pos += 1
        elif c == ord("("):
            depth += 1
            out.append(c)
            pos += 1
        elif c == ord(")"):
            depth -= 1
            pos += 1
            if depth == 0:
                break
            out.append(c)
        else:
            out.append(c)
            pos += 1
    return bytes(out), pos


def parse_hex_string(data, pos, end):
    pos += 1
    out = bytearray()
    hexbuf = []
    while pos < end and data[pos] != ord(">"):
        c = data[pos]
        if c not in b" \t\r\n\f":
            hexbuf.append(chr(c))
        pos += 1
    if pos < end:
        pos += 1
    if len(hexbuf) % 2:
        hexbuf.append("0")
    for i in range(0, len(hexbuf), 2):
        out.append(int("".join(hexbuf[i:i + 2]), 16))
    return bytes(out), pos


def parse_value(data, pos, end):
    while True:
        pos = skip_ws(data, pos, end)
        if pos < end and data[pos] == ord("%"):
            while pos < end and data[pos] not in b"\r\n":
                pos += 1
            continue
        break
    if pos >= end:
        raise PdfParseError("unexpected EOF in value")
    c = data[pos]
    if c == ord("/"):
        pos += 1
        start = pos
        while pos < end and data[pos] not in b"()<>[]{}/% \t\r\n\f":
            pos += 1
        return data[start:pos], pos
    if c == ord("("):
        return parse_literal_string(data, pos, end)
    if c == ord("<"):
        if pos + 1 < end and data[pos + 1] == ord("<"):
            return parse_dict(data, pos, end)
        return parse_hex_string(data, pos, end)
    if c == ord("["):
        pos += 1
        arr = []
        while True:
            pos = skip_ws(data, pos, end)
            if pos >= end:
                raise PdfParseError("array unterminated")
            if data[pos] == ord("]"):
                pos += 1
                break
            v, pos = parse_value(data, pos, end)
            arr.append(v)
        return arr, pos
    if c in b"]>":
        raise PdfParseError("unexpected closing bracket")
    # number / reference / keyword
    start = pos
    while pos < end and data[pos] not in b"()<>[]{}/% \t\r\n\f":
        pos += 1
    tok = data[start:pos]
    m = re.match(rb"([+-]?(?:\d+\.?\d*|\.\d+))", tok)
    if not m:
        if tok == b"true":
            return True, pos
        if tok == b"false":
            return False, pos
        if tok == b"null":
            return None, pos
        raise PdfParseError("unrecognized token %r" % tok)
    numtok = m.group(1)
    q = skip_ws(data, pos, end)
    m2 = re.match(rb"(\d+)\s+R", data[q:end])
    if m2 is not None:
        return ("ref", int(numtok), int(m2.group(1))), q + m2.end()
    if b"." in numtok:
        return float(numtok), pos
    return int(numtok), pos


def parse_dict(data, pos, end):
    pos += 2  # <<
    pairs = []
    while True:
        pos = skip_ws(data, pos, end)
        if pos >= end:
            raise PdfParseError("dict unterminated")
        if data[pos:pos + 2] == b">>":
            pos += 2
            break
        key, pos = parse_value(data, pos, end)
        if not (isinstance(key, bytes) and key.startswith(b"/")):
            raise PdfParseError("dict key expected near %r" % data[pos - 40:pos + 40])
        val, pos = parse_value(data, pos, end)
        pairs.append((key, val))
    return pairs, pos


def dict_get(pairs, name):
    for k, v in pairs:
        if k == name:
            return v
    return None


def dict_get_number(pairs, name):
    v = dict_get(pairs, name)
    if v is None:
        return None
    if isinstance(v, tuple) and v[0] == "ref":
        return ("ref", v[1], v[2])
    if isinstance(v, bool):
        return int(v)
    return int(v)


def read_object(data, offset):
    m = re.match(rb"(\d+)\s+(\d+)\s+obj\b", data[offset:])
    if not m:
        raise PdfParseError("object header missing at %d" % offset)
    objnum, gen = int(m.group(1)), int(m.group(2))
    pos = offset + m.end()
    val, pos = parse_value(data, pos, len(data))
    stream = None
    q = skip_ws(data, pos, len(data))
    if data[q:q + 6] == b"stream":
        p = q + 6
        if data[p:p + 2] == b"\r\n":
            p += 2
        elif data[p:p + 1] in (b"\n", b"\r"):
            p += 1
        length = dict_get_number(val, "/Length")
        if isinstance(length, tuple):
            raise PdfParseError("indirect /Length not supported here")
        stream = data[p:p + length]
    return objnum, gen, val, stream


def decode_stream(val, stream):
    filt = dict_get(val, "/Filter")
    if filt is None:
        return stream
    filters = filt if isinstance(filt, list) else [filt]
    for f in filters:
        if f == b"/FlateDecode":
            stream = zlib.decompress(stream)
        else:
            raise PdfParseError("unsupported stream filter %r" % f)
    return stream


def parse_object_stream(dval, sstream):
    n = dict_get_number(dval, "/N")
    first = dict_get_number(dval, "/First")
    header = sstream[:first]
    objs = {}
    for objnum_s, off_s in re.findall(rb"(\d+)\s+(\d+)", header):
        objnum = int(objnum_s)
        off = int(off_s)
        sub = sstream[off:]
        m = re.match(rb"(\d+)\s+(\d+)\s+obj\b", sub)
        if not m:
            raise PdfParseError("objstm entry malformed")
        p = m.end()
        v, _ = parse_value(sub, p, len(sub))
        objs[objnum] = v
    return objs


def parse_xref(data, xref_offset):
    pos = skip_ws(data, xref_offset, len(data))
    if data[pos:pos + 4] == b"xref":
        return parse_xref_table(data, pos)
    return parse_xref_stream(data, pos)


def parse_xref_table(data, pos):
    entries = {}
    pos += 4  # skip 'xref'
    trailer = None
    while True:
        pos = skip_ws(data, pos, len(data))
        if data[pos:pos + 7] == b"trailer":
            dbg = data[pos:pos + 160]
            try:
                trailer, _ = parse_value(data, pos + 7, len(data))
            except PdfParseError as exc:
                raise PdfParseError("trailer parse failed near %r: %s" % (dbg, exc))
            break
        m = re.match(rb"(\d+)\s+(\d+)", data[pos:])
        if not m:
            raise PdfParseError("xref subsection header missing at %d (near %r)"
                                % (pos, data[pos:pos + 80]))
        start, count = int(m.group(1)), int(m.group(2))
        pos += m.end()
        pos = skip_ws(data, pos, len(data))
        for i in range(count):
            nl = data.find(b"\n", pos)
            if nl == -1:
                nl = len(data)
            line = data[pos:nl].strip()
            pos = nl + 1
            mm = re.match(rb"(\d+)\s+(\d+)\s+([nf])", line)
            if not mm:
                raise PdfParseError("xref entry malformed: %r" % line[:40])
            objnum = start + i
            off, gen, kind = int(mm.group(1)), int(mm.group(2)), mm.group(3)
            entries[objnum] = (1 if kind == b"n" else 0, off, gen)
    if not isinstance(trailer, list):
        raise PdfParseError("xref trailer missing")
    return entries, trailer


def parse_xref_stream(data, pos):
    m = re.match(rb"(\d+)\s+(\d+)\s+obj\b", data[pos:])
    if not m:
        raise PdfParseError("xref stream header missing at %d" % pos)
    pos += m.end()
    val, pos = parse_value(data, pos, len(data))
    q = skip_ws(data, pos, len(data))
    if data[q:q + 6] != b"stream":
        raise PdfParseError("xref stream data missing")
    p = q + 6
    if data[p:p + 2] == b"\r\n":
        p += 2
    elif data[p:p + 1] in (b"\n", b"\r"):
        p += 1
    length = dict_get_number(val, "/Length")
    if isinstance(length, tuple):
        raise PdfParseError("indirect /Length in xref stream")
    raw = decode_stream(val, data[p:p + length])
    W = [int(x) for x in dict_get(val, "/W")]
    index = dict_get(val, "/Index")
    if index is None:
        index = [0, dict_get_number(val, "/Size")]
    entries = {}
    p_in = 0
    for s, c in zip(index[0::2], index[1::2]):
        for i in range(c):
            f1 = raw[p_in:p_in + W[0]]
            p_in += W[0]
            f2 = raw[p_in:p_in + W[1]]
            p_in += W[1]
            f3 = raw[p_in:p_in + W[2]]
            p_in += W[2]
            typ = int.from_bytes(f1, "big") if W[0] else 1
            a = int.from_bytes(f2, "big") if W[1] else 0
            b = int.from_bytes(f3, "big") if W[2] else 0
            entries[s + i] = (typ, a, b)
    return entries, val


def resolve_object(objnum, entries, data, cache=None):
    if cache is None:
        cache = {}
    if objnum in cache:
        return cache[objnum]
    e = entries.get(objnum)
    if e is None:
        raise PdfParseError("object %d not in xref" % objnum)
    typ, a, b = e
    if typ == 1:
        on, og, val, stream = read_object(data, a)
        cache[objnum] = (val, stream)
        return val, stream
    if typ == 2:
        sval, sstream = resolve_object(a, entries, data, cache)
        objs = parse_object_stream(sval, sstream)
        for k, v in objs.items():
            cache.setdefault(k, (v, None))
        return cache[objnum]
    raise PdfParseError("object %d is free" % objnum)


def serialize(val):
    if isinstance(val, tuple) and val[0] == "ref":
        return b"%d %d R" % (val[1], val[2])
    if isinstance(val, bytes):
        if val.startswith(b"/"):
            return val
        return b"(" + escape_ps(val.decode("latin-1")).encode("latin-1") + b")"
    if val is True:
        return b"true"
    if val is False:
        return b"false"
    if val is None:
        return b"null"
    if isinstance(val, (int, float)):
        return repr(val).encode("ascii")
    if isinstance(val, list):
        return b"[" + b" ".join(serialize(v) for v in val) + b"]"
    raise PdfParseError("cannot serialize %r" % (val,))


def serialize_pairs(pairs):
    return b" ".join(k + b" " + serialize(v) for k, v in pairs)


def add_cover_pure():
    with open(INPUT, "rb") as f:
        data = f.read()

    idx = data.rfind(b"startxref")
    if idx < 0:
        raise PdfParseError("no startxref found")
    m = re.search(rb"startxref\s+(\d+)", data[idx:])
    old_xref = int(m.group(1))

    entries, trailer = parse_xref(data, old_xref)
    if dict_get(trailer, "/Encrypt") is not None:
        raise SystemExit("error: report.pdf is encrypted; stdlib fallback cannot update it")

    root_ref = dict_get(trailer, "/Root")
    if not (isinstance(root_ref, tuple) and root_ref[0] == "ref"):
        raise PdfParseError("no /Root")
    root_val, _ = resolve_object(root_ref[1], entries, data)
    pages_ref = dict_get(root_val, "/Pages")
    if not (isinstance(pages_ref, tuple) and pages_ref[0] == "ref"):
        raise PdfParseError("no /Pages")
    pages_val, _ = resolve_object(pages_ref[1], entries, data)

    old_count = dict_get_number(pages_val, "/Count")
    old_kids = dict_get(pages_val, "/Kids")
    if not isinstance(old_kids, list):
        raise PdfParseError("no /Kids array")

    size = dict_get_number(trailer, "/Size")
    max_obj = size - 1
    n_cover, n_f1, n_f2, n_cont = max_obj + 1, max_obj + 2, max_obj + 3, max_obj + 4
    pages_objnum, pages_gen = pages_ref[1], pages_ref[2]

    content = build_cover_content()
    cont_body = (b"<< /Length %d >>\nstream\n" % len(content)) + content + b"endstream"
    f1_body = b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>"
    f2_body = b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>"
    cover_body = (b"<< /Type /Page /Parent %d %d R /MediaBox [0 0 612 792] "
                  b"/Resources << /Font << /F1 %d 0 R /F2 %d 0 R >> >> "
                  b"/Contents %d 0 R >>" % (pages_objnum, pages_gen, n_f1, n_f2, n_cont))

    kids_parts = [b"%d 0 R" % n_cover]
    for r in old_kids:
        if isinstance(r, tuple) and r[0] == "ref":
            kids_parts.append(b"%d %d R" % (r[1], r[2]))
    kept = [(k, v) for k, v in pages_val if k not in (b"/Kids", b"/Count")]
    pages_body = (b"<< /Type /Pages " + serialize_pairs(kept) +
                  b" /Kids [" + b" ".join(kids_parts) + b"] /Count %d >>"
                  % (old_count + 1))

    bodies = {
        pages_objnum: (pages_body, pages_gen),
        n_cover: (cover_body, 0),
        n_f1: (f1_body, 0),
        n_f2: (f2_body, 0),
        n_cont: (cont_body, 0),
    }

    out = bytearray(data)
    offsets = {}
    for objnum in sorted(bodies):
        body, gen = bodies[objnum]
        offsets[objnum] = len(out)
        out += ("%d %d obj\n" % (objnum, gen)).encode("ascii")
        out += body
        out += b"\nendobj\n"
    new_xref = len(out)

    out += b"xref\n0 1\n0000000000 65535 f \n"
    subsections = []
    for objnum in sorted(bodies):
        if not subsections or objnum != subsections[-1][-1] + 1:
            subsections.append([objnum])
        else:
            subsections[-1].append(objnum)
    for sub in subsections:
        out += ("%d %d\n" % (sub[0], len(sub))).encode("ascii")
        for objnum in sub:
            out += ("%010d %05d n \n" % (offsets[objnum], bodies[objnum][1])).encode("ascii")

    new_size = max(bodies) + 1
    out += ("trailer\n<< /Size %d /Root %d %d R /Prev %d >>\nstartxref\n%d\n%%EOF\n"
            % (new_size, root_ref[1], root_ref[2], old_xref, new_xref)).encode("ascii")

    fd, tmp = tempfile.mkstemp(prefix="report_cover_", suffix=".pdf",
                               dir=os.path.dirname(INPUT) or ".")
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(bytes(out))
        os.replace(tmp, INPUT)
    except Exception:
        if os.path.exists(tmp):
            os.unlink(tmp)
        raise

    # ---- validate by re-parsing ----
    with open(INPUT, "rb") as f:
        ndata = f.read()
    nidx = ndata.rfind(b"startxref")
    nm = re.search(rb"startxref\s+(\d+)", ndata[nidx:])
    nentries, ntrailer = parse_xref(ndata, int(nm.group(1)))
    nroot = dict_get(ntrailer, "/Root")
    nroot_val, _ = resolve_object(nroot[1], nentries, ndata)
    npages_ref = dict_get(nroot_val, "/Pages")
    npages_val, _ = resolve_object(npages_ref[1], nentries, ndata)
    ncount = dict_get_number(npages_val, "/Count")
    if ncount != old_count + 1:
        raise SystemExit("validation failed: /Count=%d expected %d"
                         % (ncount, old_count + 1))
    cover_val, _ = resolve_object(n_cover, nentries, ndata)
    cont_ref = dict_get(cover_val, "/Contents")
    cont_val, cont_stream = resolve_object(cont_ref[1], nentries, ndata)
    if TITLE.encode("latin-1") not in cont_stream:
        raise SystemExit("validation failed: cover title missing")
    if DATE_STR.encode("latin-1") not in cont_stream:
        raise SystemExit("validation failed: cover date missing")
    return ncount


# --------------------------------------------------------------------------
def main():
    if not os.path.exists(INPUT):
        raise SystemExit("error: %s not found" % INPUT)

    if HAVE_PIKEPDF:
        try:
            total = add_cover_pikepdf()
            method = "pikepdf"
        except SystemExit:
            raise
        except Exception as exc:
            print("pikepdf path failed (%s); trying stdlib fallback" % exc)
            total = add_cover_pure()
            method = "pure-stdlib"
    else:
        total = add_cover_pure()
        method = "pure-stdlib"

    print("OK: cover page added to %s" % INPUT)
    print("    method: %s" % method)
    print("    title: %s" % TITLE)
    print("    date:  %s" % DATE_STR)
    print("    total pages: %d" % total)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Prepend a cover page to report.pdf with title 'Annual Financial Report' and the current date.

Task-local helper: builds a one-page letter-size cover, prepends it to the
existing report pages, atomically replaces report.pdf, then validates page 1.
Uses pikepdf if available; otherwise a pure-stdlib incremental PDF update.
Only touches report.pdf (plus a temporary file that atomically replaces it).
"""
import os
import re
import tempfile
import zlib
from datetime import date

INPUT = "report.pdf"
TITLE = "Annual Financial Report"
DATE_STR = date.today().strftime("%B %d, %Y")

try:
    import pikepdf  # noqa: F401
    HAVE_PIKEPDF = True
except ImportError:
    HAVE_PIKEPDF = False


def escape_ps(s):
    return s.replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)")


def build_cover_content():
    """Return content-stream bytes for a letter-size cover with title and date."""
    w_title = 0.55 * 28 * len(TITLE)
    x1 = (612 - w_title) / 2.0
    w_date = 0.5 * 16 * len(DATE_STR)
    x2 = (612 - w_date) / 2.0
    content = (
        "BT\n/F1 28 Tf\n%.2f %.2f Td\n(%s) Tj\nET\n"
        "BT\n/F2 16 Tf\n%.2f %.2f Td\n(%s) Tj\nET\n"
        % (x1, 520.0, escape_ps(TITLE), x2, 470.0, escape_ps(DATE_STR))
    ).encode("latin-1")
    return content


# --------------------------------------------------------------------------
# pikepdf fast path
# --------------------------------------------------------------------------
def add_cover_pikepdf():
    import pikepdf
    from pikepdf import Name

    content = build_cover_content()
    with pikepdf.open(INPUT) as pdf:
        pdf.pages.insert(0, pdf.add_blank_page(page_size=(612, 792)))
        page = pdf.pages[0]
        page.Resources.Font = pikepdf.Dictionary({
            Name.F1: pdf.make_indirect(pikepdf.Dictionary({
                Name.Type: Name.Font, Name.Subtype: Name.Type1,
                Name.BaseFont: Name.HelveticaBold, Name.Encoding: Name.WinAnsiEncoding,
            })),
            Name.F2: pdf.make_indirect(pikepdf.Dictionary({
                Name.Type: Name.Font, Name.Subtype: Name.Type1,
                Name.BaseFont: Name.Helvetica, Name.Encoding: Name.WinAnsiEncoding,
            })),
        })
        page.Contents = pdf.make_indirect(pikepdf.Stream(pdf, content))
        expected = len(pdf.pages)
        fd, tmp = tempfile.mkstemp(prefix="report_cover_", suffix=".pdf",
                                   dir=os.path.dirname(INPUT) or ".")
        try:
            with os.fdopen(fd, "wb") as f:
                pdf.save(f)
            os.replace(tmp, INPUT)
        except Exception:
            if os.path.exists(tmp):
                os.unlink(tmp)
            raise

    with pikepdf.open(INPUT) as check:
        if len(check.pages) != expected:
            raise SystemExit("validation failed: pikepdf page count mismatch")
        cs = check.pages[0].Contents.read_bytes()
        if TITLE.encode("latin-1") not in cs or DATE_STR.encode("latin-1") not in cs:
            raise SystemExit("validation failed: cover text missing")
    return expected


# --------------------------------------------------------------------------
# Pure-stdlib incremental PDF update
# --------------------------------------------------------------------------
class PdfParseError(Exception):
    pass


def skip_ws(data, pos, end):
    while pos < end and data[pos] in b" \t\r\n\f\0":
        pos += 1
    return pos


def skip_comments(data, pos, end):
    while True:
        pos = skip_ws(data, pos, end)
        if pos < end and data[pos] == ord("%"):
            while pos < end and data[pos] not in b"\r\n":
                pos += 1
            continue
        return pos


def parse_literal_string(data, pos, end):
    pos += 1
    out = bytearray()
    depth = 1
    while pos < end:
        c = data[pos]
        if c == 0x5C:  # backslash
            pos += 1
            if pos >= end:
                break
            e = data[pos]
            if e in b"nrtbf":
                out.append({ord("n"): 10, ord("r"): 13, ord("t"): 9,
                            ord("b"): 8, ord("f"): 12}[e])
                pos += 1
            elif e == ord("\r"):
                pos += 1
                if pos < end and data[pos] == ord("\n"):
                    pos += 1
            elif e == ord("\n"):
                pos += 1
            elif 0x30 <= e <= 0x37:
                m = re.match(rb"[0-7]{1,3}", data[pos:pos + 3])
                out.append(int(m.group(0), 8) & 0xFF)
                pos += m.end()
            else:
                out.append(e)
                pos += 1
        elif c == ord("("):
            depth += 1
            out.append(c)
            pos += 1
        elif c == ord(")"):
            depth -= 1
            pos += 1
            if depth == 0:
                break
            out.append(c)
        else:
            out.append(c)
            pos += 1
    return bytes(out), pos


def parse_hex_string(data, pos, end):
    pos += 1
    out = bytearray()
    hexbuf = []
    while pos < end and data[pos] != ord(">"):
        c = data[pos]
        if c not in b" \t\r\n\f":
            hexbuf.append(chr(c))
        pos += 1
    if pos < end:
        pos += 1
    if len(hexbuf) % 2:
        hexbuf.append("0")
    for i in range(0, len(hexbuf), 2):
        out.append(int("".join(hexbuf[i:i + 2]), 16))
    return bytes(out), pos


def parse_value(data, pos, end):
    pos = skip_comments(data, pos, end)
    if pos >= end:
        raise PdfParseError("unexpected EOF in value")
    c = data[pos]
    if c == ord("/"):
        pos += 1
        start = pos
        while pos < end and data[pos] not in b"()<>[]{}/% \t\r\n\f":
            pos += 1
        return data[start:pos], pos
    if c == ord("("):
        return parse_literal_string(data, pos, end)
    if c == ord("<"):
        if pos + 1 < end and data[pos + 1] == ord("<"):
            return parse_dict(data, pos, end)
        return parse_hex_string(data, pos, end)
    if c == ord("["):
        pos += 1
        arr = []
        while True:
            pos = skip_comments(data, pos, end)
            if pos >= end:
                raise PdfParseError("array unterminated")
            if data[pos] == ord("]"):
                pos += 1
                break
            v, pos = parse_value(data, pos, end)
            arr.append(v)
        return arr, pos
    if c in b"]>":
        raise PdfParseError("unexpected closing bracket")
    # number / reference / keyword
    start = pos
    while pos < end and data[pos] not in b"()<>[]{}/% \t\r\n\f":
        pos += 1
    tok = data[start:pos]
    m = re.match(rb"([+-]?(?:\d+\.?\d*|\.\d+))", tok)
    if not m:
        if tok == b"true":
            return True, pos
        if tok == b"false":
            return False, pos
        if tok == b"null":
            return None, pos
        raise PdfParseError("unrecognized token %r" % tok)
    numtok = m.group(1)
    q = skip_ws(data, pos, end)
    m2 = re.match(rb"(\d+)\s+R", data[q:end])
    if m2 is not None:
        return ("ref", int(numtok), int(m2.group(1))), q + m2.end()
    if b"." in numtok:
        return float(numtok), pos
    return int(numtok), pos


def parse_dict(data, pos, end):
    pos += 2  # <<
    pairs = []
    while True:
        pos = skip_comments(data, pos, end)
        if pos >= end:
            raise PdfParseError("dict unterminated")
        if data[pos:pos + 2] == b">>":
            pos += 2
            break
        key_start = pos
        key, pos = parse_value(data, pos, end)
        if not (isinstance(key, bytes) and key.startswith(b"/")):
            raise PdfParseError(
                "dict key expected at %d (key=%r, near %r)"
                % (key_start, key, data[key_start - 60:key_start + 90]))
        val, pos = parse_value(data, pos, end)
        pairs.append((key, val))
    return pairs, pos


def dict_get(pairs, name):
    if isinstance(pairs, dict):
        return pairs.get(name)
    for k, v in pairs:
        if k == name:
            return v
    return None


def dict_get_number(pairs, name):
    v = dict_get(pairs, name)
    if v is None:
        return None
    if isinstance(v, tuple) and v[0] == "ref":
        return ("ref", v[1], v[2])
    if isinstance(v, bool):
        return int(v)
    return int(v)


def read_object(data, offset):
    m = re.match(rb"(\d+)\s+(\d+)\s+obj\b", data[offset:])
    if not m:
        raise PdfParseError("object header missing at %d" % offset)
    objnum, gen = int(m.group(1)), int(m.group(2))
    pos = offset + m.end()
    val, pos = parse_value(data, pos, len(data))
    stream = None
    q = skip_ws(data, pos, len(data))
    if data[q:q + 6] == b"stream":
        p = q + 6
        if data[p:p + 2] == b"\r\n":
            p += 2
        elif data[p:p + 1] in (b"\n", b"\r"):
            p += 1
        length = dict_get_number(val, "/Length")
        if isinstance(length, tuple):
            raise PdfParseError("indirect /Length not supported here")
        stream = data[p:p + length]
    return objnum, gen, val, stream


def decode_stream(val, stream):
    filt = dict_get(val, "/Filter")
    if filt is None:
        return stream
    filters = filt if isinstance(filt, list) else [filt]
    for f in filters:
        if f == b"/FlateDecode":
            stream = zlib.decompress(stream)
        else:
            raise PdfParseError("unsupported stream filter %r" % f)
    return stream


def parse_object_stream(dval, sstream):
    n = dict_get_number(dval, "/N")
    first = dict_get_number(dval, "/First")
    header = sstream[:first]
    objs = {}
    for objnum_s, off_s in re.findall(rb"(\d+)\s+(\d+)", header):
        objnum = int(objnum_s)
        off = int(off_s)
        sub = sstream[off:]
        m = re.match(rb"(\d+)\s+(\d+)\s+obj\b", sub)
        if not m:
            raise PdfParseError("objstm entry malformed")
        p = m.end()
        v, _ = parse_value(sub, p, len(sub))
        objs[objnum] = v
    return objs


def trailer_from_regex(raw):
    """Fallback: extract trailer values from raw bytes without full dict parse."""
    out = {}
    m = re.search(rb"/Root\s+(\d+)\s+(\d+)\s+R", raw)
    if m:
        out["/Root"] = ("ref", int(m.group(1)), int(m.group(2)))
    m = re.search(rb"/Size\s+(\d+)", raw)
    if m:
        out["/Size"] = int(m.group(1))
    m = re.search(rb"/Prev\s+(\d+)", raw)
    if m:
        out["/Prev"] = int(m.group(1))
    if re.search(rb"/Encrypt", raw):
        out["/Encrypt"] = True
    if "/Root" not in out or "/Size" not in out:
        raise PdfParseError("trailer regex fallback incomplete: %r" % raw[:300])
    return out


def parse_xref(data, xref_offset):
    pos = skip_ws(data, xref_offset, len(data))
    if data[pos:pos + 4] == b"xref":
        return parse_xref_table(data, pos)
    return parse_xref_stream(data, pos)


def parse_xref_table(data, pos):
    entries = {}
    pos += 4  # skip 'xref'
    trailer = None
    while True:
        pos = skip_ws(data, pos, len(data))
        if data[pos:pos + 7] == b"trailer":
            tpos = pos
            try:
                trailer, _ = parse_value(data, pos + 7, len(data))
            except PdfParseError as exc:
                raw = data[tpos:tpos + 600]
                raw = raw.split(b"startxref")[0]
                print("note: full trailer parse failed (%s); using regex fallback" % exc)
                trailer = trailer_from_regex(raw)
            break
        m = re.match(rb"(\d+)\s+(\d+)", data[pos:])
        if not m:
            raise PdfParseError("xref subsection header missing at %d (near %r)"
                                % (pos, data[pos:pos + 80]))
        start, count = int(m.group(1)), int(m.group(2))
        pos += m.end()
        pos = skip_ws(data, pos, len(data))
        for i in range(count):
            nl = data.find(b"\n", pos)
            if nl == -1:
                nl = len(data)
            line = data[pos:nl].strip()
            pos = nl + 1
            mm = re.match(rb"(\d+)\s+(\d+)\s+([nf])", line)
            if not mm:
                raise PdfParseError("xref entry malformed: %r" % line[:40])
            objnum = start + i
            off, gen, kind = int(mm.group(1)), int(mm.group(2)), mm.group(3)
            entries[objnum] = (1 if kind == b"n" else 0, off, gen)
    if not (isinstance(trailer, list) or isinstance(trailer, dict)):
        raise PdfParseError("xref trailer missing")
    return entries, trailer


def parse_xref_stream(data, pos):
    m = re.match(rb"(\d+)\s+(\d+)\s+obj\b", data[pos:])
    if not m:
        raise PdfParseError("xref stream header missing at %d" % pos)
    pos += m.end()
    val, pos = parse_value(data, pos, len(data))
    q = skip_ws(data, pos, len(data))
    if data[q:q + 6] != b"stream":
        raise PdfParseError("xref stream data missing")
    p = q + 6
    if data[p:p + 2] == b"\r\n":
        p += 2
    elif data[p:p + 1] in (b"\n", b"\r"):
        p += 1
    length = dict_get_number(val, "/Length")
    if isinstance(length, tuple):
        raise PdfParseError("indirect /Length in xref stream")
    raw = decode_stream(val, data[p:p + length])
    W = [int(x) for x in dict_get(val, "/W")]
    index = dict_get(val, "/Index")
    if index is None:
        index = [0, dict_get_number(val, "/Size")]
    entries = {}
    p_in = 0
    for s, c in zip(index[0::2], index[1::2]):
        for i in range(c):
            f1 = raw[p_in:p_in + W[0]]
            p_in += W[0]
            f2 = raw[p_in:p_in + W[1]]
            p_in += W[1]
            f3 = raw[p_in:p_in + W[2]]
            p_in += W[2]
            typ = int.from_bytes(f1, "big") if W[0] else 1
            a = int.from_bytes(f2, "big") if W[1] else 0
            b = int.from_bytes(f3, "big") if W[2] else 0
            entries[s + i] = (typ, a, b)
    return entries, val


def resolve_object(objnum, entries, data, cache=None):
    if cache is None:
        cache = {}
    if objnum in cache:
        return cache[objnum]
    e = entries.get(objnum)
    if e is None:
        raise PdfParseError("object %d not in xref" % objnum)
    typ, a, b = e
    if typ == 1:
        on, og, val, stream = read_object(data, a)
        cache[objnum] = (val, stream)
        return val, stream
    if typ == 2:
        sval, sstream = resolve_object(a, entries, data, cache)
        objs = parse_object_stream(sval, sstream)
        for k, v in objs.items():
            cache.setdefault(k, (v, None))
        return cache[objnum]
    raise PdfParseError("object %d is free" % objnum)


def serialize(val):
    if isinstance(val, tuple) and val[0] == "ref":
        return b"%d %d R" % (val[1], val[2])
    if isinstance(val, bytes):
        if val.startswith(b"/"):
            return val
        return b"(" + escape_ps(val.decode("latin-1")).encode("latin-1") + b")"
    if val is True:
        return b"true"
    if val is False:
        return b"false"
    if val is None:
        return b"null"
    if isinstance(val, (int, float)):
        return repr(val).encode("ascii")
    if isinstance(val, list):
        return b"[" + b" ".join(serialize(v) for v in val) + b"]"
    raise PdfParseError("cannot serialize %r" % (val,))


def serialize_pairs(pairs):
    return b" ".join(k + b" " + serialize(v) for k, v in pairs)


def add_cover_pure():
    with open(INPUT, "rb") as f:
        data = f.read()

    idx = data.rfind(b"startxref")
    if idx < 0:
        raise PdfParseError("no startxref found")
    m = re.search(rb"startxref\s+(\d+)", data[idx:])
    old_xref = int(m.group(1))

    entries, trailer = parse_xref(data, old_xref)
    if dict_get(trailer, "/Encrypt") is not None:
        raise SystemExit("error: report.pdf is encrypted; stdlib fallback cannot update it")

    root_ref = dict_get(trailer, "/Root")
    if not (isinstance(root_ref, tuple) and root_ref[0] == "ref"):
        raise PdfParseError("no /Root")
    root_val, _ = resolve_object(root_ref[1], entries, data)
    pages_ref = dict_get(root_val, "/Pages")
    if not (isinstance(pages_ref, tuple) and pages_ref[0] == "ref"):
        raise PdfParseError("no /Pages")
    pages_val, _ = resolve_object(pages_ref[1], entries, data)

    old_count = dict_get_number(pages_val, "/Count")
    old_kids = dict_get(pages_val, "/Kids")
    if not isinstance(old_kids, list):
        raise PdfParseError("no /Kids array")

    size = dict_get_number(trailer, "/Size")
    max_obj = size - 1
    n_cover, n_f1, n_f2, n_cont = max_obj + 1, max_obj + 2, max_obj + 3, max_obj + 4
    pages_objnum, pages_gen = pages_ref[1], pages_ref[2]

    content = build_cover_content()
    cont_body = (b"<< /Length %d >>\nstream\n" % len(content)) + content + b"endstream"
    f1_body = b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>"
    f2_body = b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>"
    cover_body = (b"<< /Type /Page /Parent %d %d R /MediaBox [0 0 612 792] "
                  b"/Resources << /Font << /F1 %d 0 R /F2 %d 0 R >> >> "
                  b"/Contents %d 0 R >>" % (pages_objnum, pages_gen, n_f1, n_f2, n_cont))

    kids_parts = [b"%d 0 R" % n_cover]
    for r in old_kids:
        if isinstance(r, tuple) and r[0] == "ref":
            kids_parts.append(b"%d %d R" % (r[1], r[2]))
    kept = [(k, v) for k, v in pages_val if k not in (b"/Kids", b"/Count")]
    pages_body = (b"<< /Type /Pages " + serialize_pairs(kept) +
                  b" /Kids [" + b" ".join(kids_parts) + b"] /Count %d >>"
                  % (old_count + 1))

    bodies = {
        pages_objnum: (pages_body, pages_gen),
        n_cover: (cover_body, 0),
        n_f1: (f1_body, 0),
        n_f2: (f2_body, 0),
        n_cont: (cont_body, 0),
    }

    out = bytearray(data)
    offsets = {}
    for objnum in sorted(bodies):
        body, gen = bodies[objnum]
        offsets[objnum] = len(out)
        out += ("%d %d obj\n" % (objnum, gen)).encode("ascii")
        out += body
        out += b"\nendobj\n"
    new_xref = len(out)

    out += b"xref\n0 1\n0000000000 65535 f \n"
    subsections = []
    for objnum in sorted(bodies):
        if not subsections or objnum != subsections[-1][-1] + 1:
            subsections.append([objnum])
        else:
            subsections[-1].append(objnum)
    for sub in subsections:
        out += ("%d %d\n" % (sub[0], len(sub))).encode("ascii")
        for objnum in sub:
            out += ("%010d %05d n \n" % (offsets[objnum], bodies[objnum][1])).encode("ascii")

    new_size = max(bodies) + 1
    out += ("trailer\n<< /Size %d /Root %d %d R /Prev %d >>\nstartxref\n%d\n%%EOF\n"
            % (new_size, root_ref[1], root_ref[2], old_xref, new_xref)).encode("ascii")

    fd, tmp = tempfile.mkstemp(prefix="report_cover_", suffix=".pdf",
                               dir=os.path.dirname(INPUT) or ".")
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(bytes(out))
        os.replace(tmp, INPUT)
    except Exception:
        if os.path.exists(tmp):
            os.unlink(tmp)
        raise

    # ---- validate by re-parsing ----
    with open(INPUT, "rb") as f:
        ndata = f.read()
    nidx = ndata.rfind(b"startxref")
    nm = re.search(rb"startxref\s+(\d+)", ndata[nidx:])
    nentries, ntrailer = parse_xref(ndata, int(nm.group(1)))
    nroot = dict_get(ntrailer, "/Root")
    nroot_val, _ = resolve_object(nroot[1], nentries, ndata)
    npages_ref = dict_get(nroot_val, "/Pages")
    npages_val, _ = resolve_object(npages_ref[1], nentries, ndata)
    ncount = dict_get_number(npages_val, "/Count")
    if ncount != old_count + 1:
        raise SystemExit("validation failed: /Count=%d expected %d"
                         % (ncount, old_count + 1))
    cover_val, _ = resolve_object(n_cover, nentries, ndata)
    cont_ref = dict_get(cover_val, "/Contents")
    cont_val, cont_stream = resolve_object(cont_ref[1], nentries, ndata)
    if TITLE.encode("latin-1") not in cont_stream:
        raise SystemExit("validation failed: cover title missing")
    if DATE_STR.encode("latin-1") not in cont_stream:
        raise SystemExit("validation failed: cover date missing")
    return ncount


# --------------------------------------------------------------------------
def main():
    if not os.path.exists(INPUT):
        raise SystemExit("error: %s not found" % INPUT)

    if HAVE_PIKEPDF:
        try:
            total = add_cover_pikepdf()
            method = "pikepdf"
        except SystemExit:
            raise
        except Exception as exc:
            print("pikepdf path failed (%s); trying stdlib fallback" % exc)
            total = add_cover_pure()
            method = "pure-stdlib"
    else:
        total = add_cover_pure()
        method = "pure-stdlib"

    print("OK: cover page added to %s" % INPUT)
    print("    method: %s" % method)
    print("    title: %s" % TITLE)
    print("    date:  %s" % DATE_STR)
    print("    total pages: %d" % total)


if __name__ == "__main__":
    main()

